SELECT id, username, name, role, class_name, status, last_login_at, created_at
FROM sys_user
WHERE deleted = 0

    AND role = #{role}


    AND status = #{status}


    AND (username LIKE CONCAT('%', #{keyword}, '%')
         OR name LIKE CONCAT('%', #{keyword}, '%')
         OR class_name LIKE CONCAT('%', #{keyword}, '%')
         OR student_no LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM sys_user WHERE deleted = 0
AND role = #{role}
AND status = #{status}
AND (username LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%') OR class_name LIKE CONCAT('%', #{keyword}, '%') OR student_no LIKE CONCAT('%', #{keyword}, '%'))
